.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #404249;
    color: #f2f3f5;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    background: #232428;
    margin: 0.5rem;
    border-radius: 6px;
}

.thread-divider {
    border: none;
    border-top: 1px solid #3f4147;
    margin: 0.5rem 1rem;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 1rem;
}

.thread-reply {
    padding: 0.4rem 0;
    margin-bottom: 0.25rem;
}

