    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, int> replyCounts = new();
    private bool loadingMore;
    private bool hasMoreMessages = true;
    private const int PageSize = 30;

    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    private ElementReference messageListRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = [];
        replyCounts = new();
        hasMoreMessages = true;
        threadOpen = false;

        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Update unread count in local state
        var idx = channels.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task LoadMessages()
    {
        if (selectedChannel is null) return;

        var newMessages = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        if (newMessages.Count < PageSize)
        {
            hasMoreMessages = false;
        }

        // Prepend older messages
        messages.InsertRange(0, newMessages);
        BuildReplyCounts();
    }

    private void BuildReplyCounts()
    {
        replyCounts.Clear();
        foreach (var msg in messages.Where(m => m.ReplyToId.HasValue))
        {
            var rootId = msg.ReplyToId!.Value;
            replyCounts.TryGetValue(rootId, out var count);
            replyCounts[rootId] = count + 1;
        }
    }

    private int GetReplyCount(int messageId) =>
        replyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading older messages
        if (!loadingMore && hasMoreMessages)
        {
            loadingMore = true;
            await LoadMessages();
            loadingMore = false;
        }
    }

